"use client";
import { experimental_useObject as useObject } from "@ai-sdk/react";
import { z } from "zod";

export default function Page() {
  const { object, submit, isLoading, stop } = useObject({
    api: "/api/use-object",
    schema: z.object({ content: z.string() }),
  });

  return (
    <div>
      <button onClick={() => submit("example input")} disabled={isLoading}>
        Generate
      </button>
      <button onClick={stop}>Stop</button>
      {object?.content && <p>{object.content}</p>}
    </div>
  );
}

import { generateText } from 'ai';
import { openai } from '@ai-sdk/openai';
import { vercelEmbedding, vercelTool } from '@vectorstores/vercel';
import { Document, VectorStoreIndex } from '@vectorstores/core';

const index = await VectorStoreIndex.fromDocuments(
  [new Document({ text: 'A burrito costs $10.' })],
  { embedFunc: vercelEmbedding(openai.embedding('text-embedding-3-small')) },
);

const { text } = await generateText({
  model: openai('gpt-5-mini'),
  tools: {
    search: vercelTool({
      retriever: index.asRetriever(),
      description: 'Search the knowledge base for pricing information',
    }),
  },
  prompt: 'What is the price of a burrito?',
});

console.log(text);

